-- Каталог на октябрь 2026: актуальные модели, цены российских магазинов (в основном Регард) и характеристики производителей.
-- Старые товары не удаляем: на них ссылаются прошлые заказы. Они просто снимаются с продажи.
UPDATE product SET active = FALSE;

UPDATE category SET filters = '[{"key": "chip_vendor", "label": "Производитель чипа"}, {"key": "gpu_chip", "label": "Видеочип"}, {"key": "memory_gb", "label": "Видеопамять, ГБ"}]' WHERE slug = 'gpu';
UPDATE category SET filters = '[{"key": "socket", "label": "Сокет"}, {"key": "chipset", "label": "Чипсет"}, {"key": "memory_type", "label": "Тип памяти"}, {"key": "form_factor", "label": "Форм-фактор"}]' WHERE slug = 'motherboard';
UPDATE category SET filters = '[{"key": "memory_type", "label": "Тип памяти"}, {"key": "capacity_gb", "label": "Объём, ГБ"}, {"key": "frequency", "label": "Частота, МГц"}]' WHERE slug = 'ram';
UPDATE category SET filters = '[{"key": "form_factor", "label": "Макс. плата"}, {"key": "color", "label": "Цвет"}]' WHERE slug = 'case';
UPDATE category SET filters = '[{"key": "power", "label": "Мощность, Вт"}, {"key": "certificate", "label": "Сертификат"}]' WHERE slug = 'psu';

ON CONFLICT (slug) DO UPDATE SET category_id = EXCLUDED.category_id, name = EXCLUDED.name, brand = EXCLUDED.brand,
    price = EXCLUDED.price, stock = EXCLUDED.stock, description = EXCLUDED.description,
    attributes = EXCLUDED.attributes, active = TRUE;
